package com.vuelossanitarios.backend.service;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.vuelossanitarios.backend.api.ApiException;
import com.vuelossanitarios.backend.api.dto.GeographicCatalogDtos.*;
import com.vuelossanitarios.backend.domain.catalog.*;
import com.vuelossanitarios.backend.domain.user.User;
import com.vuelossanitarios.backend.repository.*;
import java.util.*;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Mantenimiento seguro del catálogo geográfico. No hay borrado físico: los vuelos conservan sus FKs históricas. */
@Service public class GeographicCatalogService {
 private final ProvinceRepository provinces; private final LocalityRepository localities; private final AirportRepository airports; private final AircraftRepository aircraft; private final FlightRepository flights; private final UserRepository users; private final AuditService audit; private final ObjectMapper json;
 public GeographicCatalogService(ProvinceRepository p,LocalityRepository l,AirportRepository a,AircraftRepository ac,FlightRepository f,UserRepository u,AuditService au,ObjectMapper j){provinces=p;localities=l;airports=a;aircraft=ac;flights=f;users=u;audit=au;json=j;}
 private ApiException bad(String m){return new ApiException(HttpStatus.BAD_REQUEST,m);} private ApiException conflict(String c,String m){return new ApiException(HttpStatus.CONFLICT,c,m,Map.of());}
 private User actor(Long id){return users.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Usuario inexistente"));}
 private String value(String v){return v==null?null:v.trim();} private String required(String v){return value(v);}
 private String code(String v){return value(v)==null?null:value(v).toUpperCase(Locale.ROOT);}
 private String json(Object v){try{return json.writeValueAsString(v);}catch(JsonProcessingException e){throw new IllegalStateException(e);}}
 private Province province(Long id){return provinces.findById(id).filter(x->Boolean.TRUE.equals(x.getActivo())).orElseThrow(()->bad("Seleccione una provincia activa válida"));}
 private Locality locality(Long id,Province p){if(id==null)return null;Locality l=localities.findByIdAndActivoTrue(id).orElseThrow(()->bad("Seleccione una localidad activa válida"));if(!l.getProvincia().getId().equals(p.getId()))throw bad("La localidad debe pertenecer a la provincia indicada");return l;}
 public List<ProvinceAdminView> provinces(){return provinces.findAllByOrderByNombreAsc().stream().map(this::view).toList();}
 public List<LocalityAdminView> localities(){return localities.findAllByOrderByNombreAsc().stream().map(this::view).toList();}
 public List<AirportAdminView> airports(){return airports.findAllDetailedOrderByNombre().stream().map(this::view).toList();}
 @Transactional public ProvinceAdminView createProvince(ProvinceRequest r,Long actorId){String c=code(r.codigoOficial()),n=required(r.nombre());if(provinces.existsByCodigoOficialIgnoreCase(c)||provinces.existsByNombreIgnoreCase(n))throw conflict("DUPLICATE_GEOGRAPHIC_CODE","Ya existe una provincia con ese código o nombre");Province p=new Province();p.setCodigoOficial(c);p.setNombre(n);p.setActivo(true);try{provinces.saveAndFlush(p);}catch(DataIntegrityViolationException e){throw conflict("DUPLICATE_GEOGRAPHIC_CODE","Ya existe una provincia con ese código o nombre");}audit.record(null,actor(actorId),"GEOGRAPHIC_PROVINCE",p.getId(),"CREATE",null,json(view(p)));return view(p);}
 @Transactional public ProvinceAdminView updateProvince(Long id,ProvinceRequest r,Long actorId){Province p=provinces.lockById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Provincia inexistente"));String c=code(r.codigoOficial()),n=required(r.nombre());if(provinces.existsByCodigoOficialIgnoreCaseAndIdNot(c,id)||provinces.existsByNombreIgnoreCaseAndIdNot(n,id))throw conflict("DUPLICATE_GEOGRAPHIC_CODE","Ya existe una provincia con ese código o nombre");var before=view(p);p.setCodigoOficial(c);p.setNombre(n);try{provinces.saveAndFlush(p);}catch(DataIntegrityViolationException e){throw conflict("DUPLICATE_GEOGRAPHIC_CODE","Ya existe una provincia con ese código o nombre");}audit.record(null,actor(actorId),"GEOGRAPHIC_PROVINCE",id,"UPDATE",json(before),json(view(p)));return view(p);}
 @Transactional public ProvinceAdminView setProvinceActive(Long id,ActiveRequest r,Long actorId){Province p=provinces.lockById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Provincia inexistente"));if(Boolean.TRUE.equals(p.getActivo())==r.activo())throw conflict("GEOGRAPHIC_STATE_UNCHANGED","La provincia ya tiene ese estado");if(!r.activo()&&(localities.countByProvincia_IdAndActivoTrue(id)>0||airports.countByProvinciaReferencial_IdAndActivoTrue(id)>0))throw conflict("GEOGRAPHIC_HAS_ACTIVE_DEPENDENCIES","No se puede desactivar una provincia con localidades o aeropuertos activos");var before=view(p);p.setActivo(r.activo());audit.record(null,actor(actorId),"GEOGRAPHIC_PROVINCE",id,"SET_ACTIVE",json(before),json(state(r.activo(),r.motivo())));return view(p);}
 @Transactional public LocalityAdminView createLocality(LocalityRequest r,Long actorId){Province p=province(r.provinciaId());String c=code(r.codigoOficial()),n=required(r.nombre());if(localities.existsByCodigoOficialIgnoreCase(c)||localities.existsByProvincia_IdAndNombreIgnoreCase(p.getId(),n))throw conflict("DUPLICATE_GEOGRAPHIC_CODE","Ya existe una localidad con ese código o nombre en la provincia");Locality l=new Locality();l.setCodigoOficial(c);l.setNombre(n);l.setProvincia(p);l.setActivo(true);try{localities.saveAndFlush(l);}catch(DataIntegrityViolationException e){throw conflict("DUPLICATE_GEOGRAPHIC_CODE","Ya existe una localidad con ese código o nombre en la provincia");}audit.record(null,actor(actorId),"GEOGRAPHIC_LOCALITY",l.getId(),"CREATE",null,json(view(l)));return view(l);}
 @Transactional public LocalityAdminView updateLocality(Long id,LocalityRequest r,Long actorId){Locality l=localities.lockById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Localidad inexistente"));Province p=province(r.provinciaId());String c=code(r.codigoOficial()),n=required(r.nombre());if(localities.existsByCodigoOficialIgnoreCaseAndIdNot(c,id)||localities.existsByProvincia_IdAndNombreIgnoreCaseAndIdNot(p.getId(),n,id))throw conflict("DUPLICATE_GEOGRAPHIC_CODE","Ya existe una localidad con ese código o nombre en la provincia");var before=view(l);l.setCodigoOficial(c);l.setNombre(n);l.setProvincia(p);try{localities.saveAndFlush(l);}catch(DataIntegrityViolationException e){throw conflict("DUPLICATE_GEOGRAPHIC_CODE","Ya existe una localidad con ese código o nombre en la provincia");}audit.record(null,actor(actorId),"GEOGRAPHIC_LOCALITY",id,"UPDATE",json(before),json(view(l)));return view(l);}
 @Transactional public LocalityAdminView setLocalityActive(Long id,ActiveRequest r,Long actorId){Locality l=localities.lockById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Localidad inexistente"));if(Boolean.TRUE.equals(l.getActivo())==r.activo())throw conflict("GEOGRAPHIC_STATE_UNCHANGED","La localidad ya tiene ese estado");if(!r.activo()&&airports.countByLocalidad_IdAndActivoTrue(id)>0)throw conflict("GEOGRAPHIC_HAS_ACTIVE_DEPENDENCIES","No se puede desactivar una localidad con aeropuertos activos");var before=view(l);l.setActivo(r.activo());audit.record(null,actor(actorId),"GEOGRAPHIC_LOCALITY",id,"SET_ACTIVE",json(before),json(state(r.activo(),r.motivo())));return view(l);}
 @Transactional public AirportAdminView createAirport(AirportRequest r,Long actorId){Airport a=new Airport();write(a,r);assertUnique(a,null);a.setActivo(true);try{airports.saveAndFlush(a);}catch(DataIntegrityViolationException e){throw conflict("DUPLICATE_AIRPORT_CODE","Ya existe un aeropuerto con alguno de esos códigos");}audit.record(null,actor(actorId),"GEOGRAPHIC_AIRPORT",a.getId(),"CREATE",null,json(view(a)));return view(a);}
 @Transactional public AirportAdminView updateAirport(Long id,AirportRequest r,Long actorId){Airport a=airports.lockById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Aeropuerto inexistente"));var before=view(a);write(a,r);assertUnique(a,id);try{airports.saveAndFlush(a);}catch(DataIntegrityViolationException e){throw conflict("DUPLICATE_AIRPORT_CODE","Ya existe un aeropuerto con alguno de esos códigos");}audit.record(null,actor(actorId),"GEOGRAPHIC_AIRPORT",id,"UPDATE",json(before),json(view(a)));return view(a);}
 @Transactional public AirportAdminView setAirportActive(Long id,ActiveRequest r,Long actorId){Airport a=airports.lockById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Aeropuerto inexistente"));if(Boolean.TRUE.equals(a.getActivo())==r.activo())throw conflict("GEOGRAPHIC_STATE_UNCHANGED","El aeropuerto ya tiene ese estado");if(!r.activo()&&(aircraft.existsByAeropuertoActualIdAndActivoTrue(id)||flights.existsByOrigenIdOrDestinoId(id,id)))throw conflict("AIRPORT_HAS_REFERENCES","No se puede desactivar un aeropuerto con aeronaves activas o vuelos históricos; conserve su trazabilidad");var before=view(a);a.setActivo(r.activo());audit.record(null,actor(actorId),"GEOGRAPHIC_AIRPORT",id,"SET_ACTIVE",json(before),json(state(r.activo(),r.motivo())));return view(a);}
 private void write(Airport a,AirportRequest r){Province p=province(r.provinciaId());a.setCodigoOficial(code(r.codigoOficial()));a.setCodigoOaci(code(r.codigoOaci()));a.setCodigoIata(code(r.codigoIata()));a.setNombre(required(r.nombre()));a.setCiudad(value(r.ciudad()));a.setProvincia(p.getNombre());a.setProvinciaReferencial(p);a.setLocalidad(locality(r.localidadId(),p));a.setTipo(value(r.tipo()));a.setPais(required(r.pais()));a.setLatitud(r.latitud());a.setLongitud(r.longitud());}
 private void assertUnique(Airport a,Long id){if(a.getCodigoOficial()!=null&&(id==null?airports.existsByCodigoOficialIgnoreCase(a.getCodigoOficial()):airports.existsByCodigoOficialIgnoreCaseAndIdNot(a.getCodigoOficial(),id)))throw conflict("DUPLICATE_AIRPORT_CODE","El código oficial ya está registrado");if(a.getCodigoOaci()!=null&&(id==null?airports.existsByCodigoOaciIgnoreCase(a.getCodigoOaci()):airports.existsByCodigoOaciIgnoreCaseAndIdNot(a.getCodigoOaci(),id)))throw conflict("DUPLICATE_AIRPORT_CODE","El código OACI ya está registrado");if(a.getCodigoIata()!=null&&(id==null?airports.existsByCodigoIataIgnoreCase(a.getCodigoIata()):airports.existsByCodigoIataIgnoreCaseAndIdNot(a.getCodigoIata(),id)))throw conflict("DUPLICATE_AIRPORT_CODE","El código IATA ya está registrado");}
 private Map<String,Object> state(boolean active,String reason){Map<String,Object> v=new LinkedHashMap<>();v.put("activo",active);v.put("motivo",value(reason));return v;}
 private ProvinceAdminView view(Province p){return new ProvinceAdminView(p.getId(),p.getCodigoOficial(),p.getNombre(),Boolean.TRUE.equals(p.getActivo()));} private LocalityAdminView view(Locality l){return new LocalityAdminView(l.getId(),l.getCodigoOficial(),l.getNombre(),l.getProvincia().getId(),l.getProvincia().getNombre(),Boolean.TRUE.equals(l.getActivo()));} private AirportAdminView view(Airport a){Province p=a.getProvinciaReferencial();Locality l=a.getLocalidad();return new AirportAdminView(a.getId(),a.getCodigoOficial(),a.getCodigoOaci(),a.getCodigoIata(),a.getNombre(),a.getCiudad(),p==null?null:p.getId(),p==null?null:p.getNombre(),l==null?null:l.getId(),l==null?null:l.getNombre(),a.getTipo(),a.getPais(),a.getLatitud(),a.getLongitud(),Boolean.TRUE.equals(a.getActivo()));}
}
